import { Database } from 'bun:sqlite';
import { mkdir, mkdtemp, readdir, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { format, resolveConfig } from 'prettier';
import ts from 'typescript';
import { SqliteMapPlaceStore } from '@/lib/map/sqlite';

/**
 * Banner placed at the top of every generated database page.
 */
export const GENERATED_HEADER =
  '<!-- Generated by integration/db-schema-reference.ts - do not edit. Run: bun run db:docs -->';

/**
 * One column from `PRAGMA table_xinfo`.
 *
 * `primaryKeyPosition` is the pragma's `pk` value: `0` when the column is not part of the
 * primary key, otherwise its 1-based position within the key.
 */
export type SqliteColumn = {
  cid: number;
  name: string;
  type: string;
  notNull: boolean;
  defaultValue: string | null;
  primaryKeyPosition: number;
  hidden: number;
};

/**
 * One row from `PRAGMA foreign_key_list`.
 *
 * `to` is null when the foreign key targets the parent table's primary key.
 */
export type SqliteForeignKey = {
  id: number;
  seq: number;
  refTable: string;
  from: string;
  to: string | null;
};

/**
 * One index from `PRAGMA index_list` plus its column names.
 *
 * `origin` is `c` (plain index), `u` (unique constraint), or `pk` (primary key).
 */
export type SqliteIndex = {
  name: string;
  unique: boolean;
  origin: string;
  partial: boolean;
  columns: string[];
};

/**
 * One SQLite table as returned by the catalog pragmas, before modelling.
 */
export type RawTable = {
  name: string;
  columns: SqliteColumn[];
  foreignKeys: SqliteForeignKey[];
  indexes: SqliteIndex[];
};

/**
 * One column on a generated table page.
 */
export type ColumnModel = {
  name: string;
  kind: string;
  dbType: string;
  nullable: boolean;
  defaultText: string;
  references: { table: string; column: string } | null;
};

/**
 * One foreign key from the referencing table's point of view.
 */
export type ForeignKeyModel = {
  table: string;
  column: string;
  refTable: string;
  refColumn: string;
  nullable: boolean;
  unique: boolean;
};

/**
 * One index rendered on a table page. Automatic index names are kept here and omitted from the page.
 */
export type IndexModel = {
  name: string;
  columns: string[];
  unique: boolean;
  origin: 'index' | 'unique constraint' | 'primary key';
  partial: boolean;
};

/**
 * One table in the generated reference.
 */
export type TableModel = {
  name: string;
  columns: ColumnModel[];
  indexes: IndexModel[];
  foreignKeys: ForeignKeyModel[];
};

/**
 * The whole schema, with tables already in display order.
 */
export type SchemaModel = {
  tables: TableModel[];
};

/**
 * Maps a declared SQLite column type to the reference kind.
 *
 * Matching is case-insensitive and ignores a trailing `(...)` length. An unrecognised type,
 * including the empty string, is returned exactly as written (surrounding whitespace removed).
 * @param declaredType - Type text from the catalog.
 * @returns Kind label used in the column table.
 */
export function baseKind(declaredType: string): string {
  const written = declaredType.trim();
  const base = written
    .toUpperCase()
    .replace(/\s*\([^)]*\)\s*$/, '')
    .trim();
  // SQLite's first affinity rule: any declared type containing INT is an integer (BIGINT, SMALLINT).
  if (base.includes('INT')) return 'Integer';
  const decimalNames = ['REAL', 'DOUBLE', 'DOUBLE PRECISION', 'FLOAT', 'NUMERIC', 'DECIMAL'];
  const decimalPrefixes = ['DOUBLE', 'FLOAT', 'NUMERIC', 'DECIMAL', 'REAL'];
  if (decimalNames.includes(base) || decimalPrefixes.some((prefix) => base.startsWith(prefix))) {
    return 'Decimal';
  }
  const textPrefixes = ['TEXT', 'VARCHAR', 'CHAR', 'CLOB', 'NCHAR', 'NVARCHAR'];
  if (textPrefixes.some((prefix) => base.startsWith(prefix))) return 'Free text';
  if (base === 'BLOB') return 'Binary';
  if (base === 'BOOLEAN') return 'Boolean';
  if (base === 'DATE' || base === 'DATETIME' || base === 'TIMESTAMP') return 'Date/time';
  return written;
}

/**
 * Combines the base kind with primary-key, auto-increment, foreign-key, and enum markers.
 *
 * A primary key wins over a foreign key. Auto-increment is reported only together with a primary key.
 * @param input - Flags for one column.
 * @returns Kind cell text.
 */
export function columnKind(input: {
  base: string;
  isEnum: boolean;
  isPrimaryKey: boolean;
  isAutoIncrement: boolean;
  isForeignKey: boolean;
}): string {
  const kind = input.isEnum ? 'ENUM' : input.base;
  if (input.isPrimaryKey && input.isAutoIncrement) return 'Integer (primary key, auto-increment)';
  if (input.isPrimaryKey) return `${kind} (primary key)`;
  if (input.isForeignKey) return `${kind} (foreign key)`;
  return kind;
}

/**
 * Renders a SQLite column default for a markdown cell.
 *
 * Null becomes an en dash. A single-quoted SQL literal is unquoted (`''` inside the literal is one
 * quote) and wrapped in a code span. An empty literal is `` `''` ``. Every other expression is wrapped
 * in a code span unchanged apart from surrounding whitespace.
 * @param defaultValue - Default expression from the catalog, or null.
 * @returns Markdown for the Default column.
 */
export function renderDefault(defaultValue: string | null): string {
  if (defaultValue === null) return '–';
  const trimmed = defaultValue.trim();
  const literal = sqlStringLiteralContent(trimmed);
  if (literal !== null) {
    if (literal === '') return codeSpan("''");
    return codeSpan(literal);
  }
  if (trimmed === '') return '–';
  return codeSpan(trimmed);
}

/**
 * Crow's-foot cardinality of a foreign key from the referencing side.
 * Uniqueness is the key's own uniqueness, not a multi-column unique that merely covers it.
 */
export function cardinality(
  fkNullable: boolean,
  fkAloneUnique: boolean,
): '}o--o|' | '}o--||' | '|o--o|' | '||--||' {
  if (!fkAloneUnique) return fkNullable ? '}o--o|' : '}o--||';
  return fkNullable ? '|o--o|' : '||--||';
}

/**
 * Compares a freshly rendered path-to-text map with the committed one.
 * `missing` exists only in `rendered`, `stale` only in `committed`, `differing` in both with different text.
 * Each list is sorted by path.
 */
export function compareToCommitted(
  rendered: Map<string, string>,
  committed: Map<string, string>,
): { missing: string[]; differing: string[]; stale: string[] } {
  const missing: string[] = [];
  const differing: string[] = [];
  const stale: string[] = [];

  for (const [name, text] of rendered) {
    const previous = committed.get(name);
    if (previous === undefined) missing.push(name);
    else if (previous !== text) differing.push(name);
  }

  for (const name of committed.keys()) {
    if (!rendered.has(name)) stale.push(name);
  }

  missing.sort();
  differing.sort();
  stale.sort();
  return { missing, differing, stale };
}

/**
 * Builds a display model from pragma rows and the enum columns discovered in source.
 *
 * Output order does not depend on input order. Hidden columns (`hidden === 1`) are dropped.
 * A column is auto-increment only when it is the table's sole primary-key column and its declared
 * type is `INTEGER`. Foreign-key targets that cannot be resolved are omitted.
 * @param tables - Catalog tables.
 * @param enumColumns - Map of table name to column names the code treats as enums.
 * @returns Schema model in page order.
 */
export function buildSchemaModel(
  tables: readonly RawTable[],
  enumColumns: ReadonlyMap<string, ReadonlySet<string>>,
): SchemaModel {
  const byName = new Map<string, RawTable>();
  for (const table of tables) {
    if (!byName.has(table.name)) byName.set(table.name, table);
  }
  const sorted = [...tables].sort((left, right) => compareText(left.name, right.name));
  return {
    tables: sorted.map((table) => buildTableModel(table, byName, enumColumns)),
  };
}

/**
 * Maps each `CREATE TABLE` name under `src` to the sorted repo-relative files that declare it.
 *
 * Directories named `__tests__` are skipped. Only `.ts` files are read. Files are visited in
 * sorted path order.
 */
export async function sourceFiles(repoRoot: string): Promise<Map<string, string[]>> {
  const files = (await collectTypeScriptFiles(path.join(repoRoot, 'src'))).sort(compareText);
  const found = new Map<string, string[]>();
  for (const file of files) {
    const relative = path.relative(repoRoot, file).split(path.sep).join('/');
    const text = await readFile(file, 'utf8');
    for (const table of createTableNames(text)) {
      const list = found.get(table);
      if (list) list.push(relative);
      else found.set(table, [relative]);
    }
  }
  const result = new Map<string, string[]>();
  for (const table of [...found.keys()].sort(compareText)) {
    result.set(table, [...new Set(found.get(table) ?? [])].sort(compareText));
  }
  return result;
}

/**
 * Renders the schema README and one markdown page per table.
 *
 * Keys are `docs/database/README.md` and `docs/database/tables/<table>.md`. Each page starts
 * with {@link GENERATED_HEADER} and is formatted as Markdown with the repo Prettier config.
 * @param model - Schema to render.
 * @param sources - Repo-relative source files for each table.
 * @param repoRoot - Repository root used to load `.prettierrc`.
 * @returns Path-to-markdown map.
 */
export async function renderPages(
  model: SchemaModel,
  sources: Map<string, string[]>,
  repoRoot: string,
): Promise<Map<string, string>> {
  const resolved = await resolveConfig(path.join(repoRoot, '.prettierrc'));
  const options = { ...(resolved ?? {}), parser: 'markdown' as const };
  const pages = new Map<string, string>();
  pages.set('docs/database/README.md', await format(renderReadme(model, sources), options));
  const foreignKeys = model.tables.flatMap((table) => table.foreignKeys);
  for (const table of model.tables) {
    pages.set(
      `docs/database/tables/${table.name}.md`,
      await format(renderTablePage(table, sources.get(table.name) ?? [], foreignKeys), options),
    );
  }
  return pages;
}

/**
 * Orders two strings with the default UTF-16 comparison.
 * @param left - Left text.
 * @param right - Right text.
 * @returns Negative, zero, or positive.
 */
function compareText(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

const CREATE_TABLE_PATTERN =
  /create\s+table\s+(?:if\s+not\s+exists\s+)?(?:public\.)?"?([A-Za-z_][A-Za-z0-9_]*)\b"?/gi;

/**
 * Collects `.ts` files under `directory`, skipping `__tests__` directories.
 * @param directory - Absolute directory.
 * @returns File paths in directory order.
 */
async function collectTypeScriptFiles(directory: string): Promise<string[]> {
  const entries = await readdir(directory, { withFileTypes: true });
  const files: string[] = [];
  for (const entry of entries) {
    if (entry.isDirectory() && entry.name === '__tests__') continue;
    const fullPath = path.join(directory, entry.name);
    if (entry.isDirectory()) files.push(...(await collectTypeScriptFiles(fullPath)));
    else if (entry.isFile() && entry.name.endsWith('.ts')) files.push(fullPath);
  }
  return files;
}

/**
 * Returns every `CREATE TABLE` name in `source`.
 * @param source - TypeScript source text.
 * @returns Names in appearance order.
 */
function createTableNames(source: string): string[] {
  const names: string[] = [];
  for (const match of source.matchAll(CREATE_TABLE_PATTERN)) {
    const name = match[1];
    if (name !== undefined) names.push(name);
  }
  return names;
}

/**
 * Returns the unescaped contents of a single-quoted SQL string, or null when `value` is not one.
 * @param value - Trimmed default expression.
 * @returns Literal contents, or null.
 */
function sqlStringLiteralContent(value: string): string | null {
  if (value.length < 2 || !value.startsWith("'") || !value.endsWith("'")) return null;
  const inner = value.slice(1, -1);
  for (let index = 0; index < inner.length; index += 1) {
    if (inner.charAt(index) !== "'") continue;
    if (inner.charAt(index + 1) !== "'") return null;
    index += 1;
  }
  return inner.replace(/''/g, "'");
}

/**
 * Columns shown for a table: hidden generated columns removed, ordered by `cid`.
 * @param table - Catalog table.
 * @returns Visible columns.
 */
function visibleColumns(table: RawTable): SqliteColumn[] {
  return table.columns
    .filter((column) => column.hidden !== 1)
    .sort((left, right) => left.cid - right.cid);
}

/**
 * Primary-key columns of a visible column list, ordered by key position.
 * @param columns - Visible columns.
 * @returns Primary-key columns.
 */
function primaryKeyColumns(columns: readonly SqliteColumn[]): SqliteColumn[] {
  return columns
    .filter((column) => column.primaryKeyPosition > 0)
    .sort(
      (left, right) =>
        left.primaryKeyPosition - right.primaryKeyPosition || compareText(left.name, right.name),
    );
}

/**
 * Resolves the parent column a foreign-key row points at.
 *
 * A null `to` uses the parent primary-key column at the same `seq`.
 * @param foreignKey - Foreign-key row.
 * @param tablesByName - Catalog tables by name.
 * @returns Parent column name, or null when it cannot be resolved.
 */
function resolveRefColumn(
  foreignKey: SqliteForeignKey,
  tablesByName: ReadonlyMap<string, RawTable>,
): string | null {
  if (foreignKey.to !== null) return foreignKey.to;
  const parent = tablesByName.get(foreignKey.refTable);
  if (parent === undefined) return null;
  const target = primaryKeyColumns(visibleColumns(parent))[foreignKey.seq];
  return target === undefined ? null : target.name;
}

/**
 * Whether `column` is the only column of some non-partial unique index, including a primary key.
 * @param indexes - Catalog indexes of the referencing table.
 * @param column - Referencing column name.
 * @returns True when the column alone is unique.
 */
function columnAloneUnique(indexes: readonly SqliteIndex[], column: string): boolean {
  return indexes.some(
    (index) =>
      index.unique && !index.partial && index.columns.length === 1 && index.columns[0] === column,
  );
}

/**
 * Maps a catalog index origin to the page label.
 * @param origin - `c`, `u`, or `pk`.
 * @returns Origin text.
 */
function indexOrigin(origin: string): IndexModel['origin'] {
  if (origin === 'pk') return 'primary key';
  if (origin === 'u') return 'unique constraint';
  return 'index';
}

/**
 * Builds one table model.
 * @param table - Catalog table.
 * @param tablesByName - All catalog tables by name.
 * @param enumColumns - Enum columns discovered in source.
 * @returns Table model.
 */
function buildTableModel(
  table: RawTable,
  tablesByName: ReadonlyMap<string, RawTable>,
  enumColumns: ReadonlyMap<string, ReadonlySet<string>>,
): TableModel {
  const columns = visibleColumns(table);
  const keyColumns = primaryKeyColumns(columns);
  const soleKey = keyColumns.length === 1 ? keyColumns[0] : undefined;
  const autoIncrement = soleKey !== undefined && soleKey.type.trim().toUpperCase() === 'INTEGER';
  const foreignKeys = [...table.foreignKeys].sort(
    (left, right) => left.id - right.id || left.seq - right.seq,
  );
  const sequencesById = new Map<number, number>();
  for (const foreignKey of table.foreignKeys) {
    sequencesById.set(foreignKey.id, (sequencesById.get(foreignKey.id) ?? 0) + 1);
  }
  const foreignKeyColumns = new Set(table.foreignKeys.map((foreignKey) => foreignKey.from));
  const enums = enumColumns.get(table.name);
  const columnModels: ColumnModel[] = columns.map((column) => {
    let references: ColumnModel['references'] = null;
    for (const foreignKey of foreignKeys) {
      if (foreignKey.from !== column.name) continue;
      const refColumn = resolveRefColumn(foreignKey, tablesByName);
      if (refColumn === null) continue;
      references = { table: foreignKey.refTable, column: refColumn };
      break;
    }
    const isPrimaryKey = column.primaryKeyPosition > 0;
    return {
      name: column.name,
      kind: columnKind({
        base: baseKind(column.type),
        isEnum: enums?.has(column.name) ?? false,
        isPrimaryKey,
        isAutoIncrement: autoIncrement && soleKey?.name === column.name,
        isForeignKey: foreignKeyColumns.has(column.name),
      }),
      dbType: column.type.trim(),
      nullable: !column.notNull,
      defaultText: renderDefault(column.defaultValue),
      references,
    };
  });
  const indexes: IndexModel[] = table.indexes
    .map((index) => ({
      name: index.name,
      columns: [...index.columns],
      unique: index.unique,
      origin: indexOrigin(index.origin),
      partial: index.partial,
    }))
    .sort(
      (left, right) =>
        compareText(left.columns.join(','), right.columns.join(',')) ||
        compareText(left.origin, right.origin) ||
        compareText(left.name, right.name),
    );
  const foreignKeyModels: ForeignKeyModel[] = [];
  for (const foreignKey of foreignKeys) {
    const refColumn = resolveRefColumn(foreignKey, tablesByName);
    const source = columns.find((column) => column.name === foreignKey.from);
    if (refColumn === null || source === undefined) continue;
    const alone = (sequencesById.get(foreignKey.id) ?? 0) === 1;
    foreignKeyModels.push({
      table: table.name,
      column: foreignKey.from,
      refTable: foreignKey.refTable,
      refColumn,
      nullable: !source.notNull,
      unique: alone && columnAloneUnique(table.indexes, foreignKey.from),
    });
  }
  foreignKeyModels.sort(
    (left, right) =>
      compareText(left.column, right.column) ||
      compareText(left.refTable, right.refTable) ||
      compareText(left.refColumn, right.refColumn),
  );
  return {
    name: table.name,
    columns: columnModels,
    indexes,
    foreignKeys: foreignKeyModels,
  };
}

/**
 * Renders `docs/database/README.md`.
 * @param model - Schema model.
 * @param sources - Source files per table.
 * @returns Markdown before Prettier.
 */
function renderReadme(model: SchemaModel, sources: Map<string, string[]>): string {
  const columnCount = model.tables.reduce((total, table) => total + table.columns.length, 0);
  const foreignKeyCount = model.tables.reduce(
    (total, table) => total + table.foreignKeys.length,
    0,
  );
  const rows = model.tables.map((table) => {
    const paths = sources.get(table.name) ?? [];
    return `| ${markdownCell(`[${codeSpan(table.name)}](tables/${table.name}.md)`)} | ${markdownCell(sourceLinks(paths, '../../'))} | ${table.columns.length} | ${table.foreignKeys.length} |`;
  });
  return [
    GENERATED_HEADER,
    '',
    '# Database schema',
    '',
    'The pages are generated from the schema `SqliteMapPlaceStore` creates at boot. `ENUM` means the code allows a fixed set of values while SQLite stores `TEXT`. Regenerate with `bun run db:docs`.',
    '',
    `- Tables: ${model.tables.length}`,
    `- Columns: ${columnCount}`,
    `- Foreign keys: ${foreignKeyCount}`,
    '',
    '| Table | Source | Columns | Foreign keys |',
    '| --- | --- | --- | --- |',
    ...rows,
    '',
  ].join('\n');
}

/**
 * Renders one table page.
 * @param table - Table model.
 * @param paths - Repo-relative source files.
 * @param foreignKeys - Foreign keys of the whole schema.
 * @returns Markdown before Prettier.
 */
function renderTablePage(
  table: TableModel,
  paths: readonly string[],
  foreignKeys: readonly ForeignKeyModel[],
): string {
  const sourceLine = `Source: ${sourceLinks(paths, '../../../')}`;
  const parts = [
    GENERATED_HEADER,
    '',
    `# ${codeSpan(table.name)}`,
    '',
    sourceLine,
    '',
    '## Columns',
    '',
    renderColumns(table),
    '',
    '## Indexes',
    '',
    renderIndexes(table),
    '',
    '## Referenced by',
    '',
    renderReferencedBy(table.name, foreignKeys),
  ];
  const relations = renderRelations(table.name, foreignKeys);
  if (relations !== null) parts.push('', '## Relations', '', relations);
  parts.push('');
  return parts.join('\n');
}

/**
 * Renders the column table.
 * @param table - Table model.
 * @returns Markdown table.
 */
function renderColumns(table: TableModel): string {
  const rows = table.columns.map((column) => {
    const reference =
      column.references === null
        ? '–'
        : `[${codeSpan(column.references.table)}.${codeSpan(column.references.column)}](${column.references.table}.md)`;
    return `| ${markdownCell(codeSpan(column.name))} | ${markdownCell(column.kind)} | ${markdownCell(codeSpan(column.dbType))} | ${column.nullable ? 'Yes' : 'No'} | ${markdownCell(column.defaultText)} | ${markdownCell(reference)} |`;
  });
  return [
    '| Column | Kind | Database type | Nullable | Default | References |',
    '| --- | --- | --- | --- | --- | --- |',
    ...rows,
  ].join('\n');
}

/**
 * Renders the index table. Index names are not shown.
 * @param table - Table model.
 * @returns Markdown table, or `None.`
 */
function renderIndexes(table: TableModel): string {
  if (table.indexes.length === 0) return 'None.';
  const rows = table.indexes.map((index) => {
    const columns = index.columns.map((column) => codeSpan(column)).join(', ');
    return `| ${markdownCell(columns)} | ${index.unique ? 'Yes' : 'No'} | ${markdownCell(index.origin)} | ${index.partial ? 'Yes' : 'No'} |`;
  });
  return ['| Columns | Unique | Origin | Partial |', '| --- | --- | --- | --- |', ...rows].join(
    '\n',
  );
}

/**
 * Renders foreign keys that point at `tableName`.
 * @param tableName - Target table.
 * @param foreignKeys - Foreign keys of the whole schema.
 * @returns Markdown table, or `None.`
 */
function renderReferencedBy(tableName: string, foreignKeys: readonly ForeignKeyModel[]): string {
  const incoming = foreignKeys
    .filter((foreignKey) => foreignKey.refTable === tableName)
    .sort(
      (left, right) =>
        compareText(left.table, right.table) ||
        compareText(left.column, right.column) ||
        compareText(left.refColumn, right.refColumn),
    );
  if (incoming.length === 0) return 'None.';
  const rows = incoming.map(
    (foreignKey) =>
      `| ${markdownCell(codeSpan(foreignKey.table))} | ${markdownCell(codeSpan(foreignKey.column))} | ${markdownCell(codeSpan(foreignKey.refColumn))} |`,
  );
  return ['| Table | Column | Points to |', '| --- | --- | --- |', ...rows].join('\n');
}

/**
 * Renders an `erDiagram` of foreign keys touching `tableName`.
 * @param tableName - Table at the centre of the diagram.
 * @param foreignKeys - Foreign keys of the whole schema.
 * @returns Mermaid fence, or null when the table has no relations.
 */
function renderRelations(
  tableName: string,
  foreignKeys: readonly ForeignKeyModel[],
): string | null {
  const lines = [
    ...new Set(
      foreignKeys
        .filter((foreignKey) => foreignKey.table === tableName || foreignKey.refTable === tableName)
        .map(
          (foreignKey) =>
            `    "${escapeMermaid(foreignKey.table)}" ${cardinality(foreignKey.nullable, foreignKey.unique)} "${escapeMermaid(foreignKey.refTable)}" : "${escapeMermaid(foreignKey.column)}"`,
        ),
    ),
  ].sort(compareText);
  if (lines.length === 0) return null;
  return ['```mermaid', 'erDiagram', ...lines, '```'].join('\n');
}

/**
 * Renders repo-relative source paths as markdown links.
 * @param paths - Repo-relative files.
 * @param prefix - Relative prefix from the page to the repo root.
 * @returns Link list, or an en dash when there are no sources.
 */
function sourceLinks(paths: readonly string[], prefix: string): string {
  if (paths.length === 0) return '–';
  return paths.map((file) => `[${file}](${prefix}${file})`).join(', ');
}

/**
 * Wraps `value` in a markdown code span, turning backticks into quotes.
 * @param value - Cell text.
 * @returns Code span.
 */
function codeSpan(value: string): string {
  return `\`${value.replace(/`/g, "'")}\``;
}

/**
 * Escapes a markdown table cell.
 * @param value - Cell text.
 * @returns Single-line cell text.
 */
function markdownCell(value: string): string {
  return value.replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
}

/**
 * Escapes a mermaid identifier.
 * @param value - Raw identifier.
 * @returns Escaped text.
 */
function escapeMermaid(value: string): string {
  return value.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

/**
 * Repository root used when reading sources and writing `docs/database`.
 * One directory above this module (`integration/`).
 */
export const REPO_ROOT: string = path.resolve(import.meta.dir, '..');

/**
 * TypeScript type that corresponds to one SQLite table, when one exists.
 */
export type TableType = { file: string; typeName: string };

/**
 * Maps every SQLite table name to its TypeScript type, or `null` when the table has none.
 * Every table must have an entry; a new table needs one or the generator fails.
 */
export const TABLE_TYPES: Readonly<Record<string, TableType | null>> = {
  map_place: { file: 'src/lib/map/place.ts', typeName: 'StoredMapPlace' },
  map_place_support: { file: 'src/lib/map/place.ts', typeName: 'MapPlaceSupport' },
  map_place_payment_day: null,
};

/**
 * Converts a SQLite snake_case column name to a camelCase TypeScript property name.
 * @param column - Column name as stored in SQLite.
 * @returns The camelCase form (`shop_type` → `shopType`, `id` → `id`).
 */
export function camelCase(column: string): string {
  return column.replace(/_([a-zA-Z0-9])/g, (_match: string, letter: string): string =>
    letter.toUpperCase(),
  );
}

/**
 * Builds a TypeScript program from the repository `tsconfig.json`.
 * @param repoRoot - Absolute repository root.
 * @returns A program whose root names and options come from that config.
 */
export function createProgram(repoRoot: string): ts.Program {
  const configPath = path.join(repoRoot, 'tsconfig.json');
  const read = ts.readConfigFile(configPath, ts.sys.readFile);
  if (read.error !== undefined) {
    throw new Error(ts.flattenDiagnosticMessageText(read.error.messageText, '\n'));
  }
  const parsed = ts.parseJsonConfigFileContent(read.config, ts.sys, repoRoot);
  return ts.createProgram({ rootNames: parsed.fileNames, options: parsed.options });
}

/**
 * Column names whose TypeScript type is a literal (or enum-literal) union.
 * `string`, `number`, `boolean`, and object types are not enums. Null, undefined, and void
 * members are ignored before that test. A single remaining literal counts.
 * @param program - Program that contains `filePath`.
 * @param filePath - Absolute path of the source file declaring `typeName`.
 * @param typeName - Top-level type alias or interface name.
 * @param columns - SQLite column names to test (matched via {@link camelCase}).
 * @returns The subset of `columns` that are enums.
 */
export function enumColumnsOf(
  program: ts.Program,
  filePath: string,
  typeName: string,
  columns: readonly string[],
): ReadonlySet<string> {
  const sourceFile = program.getSourceFile(filePath);
  if (sourceFile === undefined) {
    throw new Error(`TypeScript file not found: ${filePath}`);
  }
  const declaration = sourceFile.statements.find(
    (statement: ts.Statement): statement is ts.TypeAliasDeclaration | ts.InterfaceDeclaration =>
      (ts.isTypeAliasDeclaration(statement) || ts.isInterfaceDeclaration(statement)) &&
      statement.name.text === typeName,
  );
  if (declaration === undefined) {
    throw new Error(`Type ${typeName} not found in ${filePath}`);
  }

  const checker = program.getTypeChecker();
  const type = checker.getTypeAtLocation(declaration.name);
  const literalFlags =
    ts.TypeFlags.StringLiteral | ts.TypeFlags.NumberLiteral | ts.TypeFlags.EnumLiteral;
  const skipFlags = ts.TypeFlags.Null | ts.TypeFlags.Undefined | ts.TypeFlags.Void;
  const enums = new Set<string>();

  for (const column of columns) {
    const prop = checker.getPropertyOfType(type, camelCase(column));
    if (prop === undefined) continue;
    const propType = checker.getTypeOfSymbolAtLocation(prop, declaration);
    const members = propType.isUnion() ? propType.types : [propType];
    const remaining = members.filter(
      (member: ts.Type): boolean => (member.flags & skipFlags) === 0,
    );
    if (remaining.length === 0) continue;
    if (remaining.every((member: ts.Type): boolean => (member.flags & literalFlags) !== 0)) {
      enums.add(column);
    }
  }
  return enums;
}

/**
 * Resolves ENUM columns for every raw table using {@link TABLE_TYPES}.
 * @param program - Program used to read the mapped TypeScript types.
 * @param repoRoot - Absolute repository root.
 * @param tables - Tables read from the live SQLite schema.
 * @param tableTypes - Table → type map. Defaults to {@link TABLE_TYPES}.
 * @returns Map of table name to the set of ENUM column names (empty when the entry is `null`).
 */
export function resolveEnumColumns(
  program: ts.Program,
  repoRoot: string,
  tables: readonly RawTable[],
  tableTypes: Readonly<Record<string, TableType | null>> = TABLE_TYPES,
): Map<string, ReadonlySet<string>> {
  const resolved = new Map<string, ReadonlySet<string>>();
  for (const table of tables) {
    if (!Object.prototype.hasOwnProperty.call(tableTypes, table.name)) {
      throw new Error(
        `Table "${table.name}" has no entry in TABLE_TYPES in integration/db-schema-reference.ts - add one (a TypeScript type, or null).`,
      );
    }
    const entry = tableTypes[table.name];
    if (entry === undefined) {
      throw new Error(
        `Table "${table.name}" has no entry in TABLE_TYPES in integration/db-schema-reference.ts - add one (a TypeScript type, or null).`,
      );
    }
    if (entry === null) {
      resolved.set(table.name, new Set<string>());
      continue;
    }
    const columnNames = table.columns
      .filter((column: SqliteColumn): boolean => column.hidden === 0)
      .map((column: SqliteColumn): string => column.name);
    resolved.set(
      table.name,
      enumColumnsOf(
        program,
        path.join(repoRoot, ...entry.file.split('/')),
        entry.typeName,
        columnNames,
      ),
    );
  }
  return resolved;
}

type XInfoRow = {
  cid: number;
  name: string;
  type: string;
  notnull: number;
  dflt_value: string | null;
  pk: number;
  hidden: number;
};

type ForeignKeyListRow = {
  id: number;
  seq: number;
  table: string;
  from: string;
  to: string;
};

type IndexListRow = {
  name: string;
  unique: number;
  origin: string;
  partial: number;
};

/**
 * Reads tables, columns, foreign keys, and indexes from an open SQLite database.
 * @param db - Database to inspect. The caller owns its lifetime.
 * @returns One {@link RawTable} per user table, ordered by name.
 */
export function readRawSchema(db: Database): RawTable[] {
  const tableSql =
    "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite\\_%' ESCAPE '\\' ORDER BY name";
  const tableRows = db.query(tableSql).all() as Array<{ name: string }>;

  return tableRows.map((tableRow: { name: string }): RawTable => {
    const t = tableRow.name;
    const q = '"' + t.replaceAll('"', '""') + '"';
    const xinfo = db.query(`PRAGMA table_xinfo(${q})`).all() as Array<XInfoRow>;
    const foreignKeyRows = db
      .query(`PRAGMA foreign_key_list(${q})`)
      .all() as Array<ForeignKeyListRow>;
    const indexRows = db.query(`PRAGMA index_list(${q})`).all() as Array<IndexListRow>;

    const columns: SqliteColumn[] = xinfo.map((row: XInfoRow): SqliteColumn => ({
      cid: row.cid,
      name: row.name,
      type: row.type,
      notNull: row.notnull === 1,
      defaultValue: row.dflt_value,
      primaryKeyPosition: row.pk,
      hidden: row.hidden,
    }));

    const foreignKeys: SqliteForeignKey[] = foreignKeyRows.map(
      (row: ForeignKeyListRow): SqliteForeignKey => ({
        id: row.id,
        seq: row.seq,
        refTable: row.table,
        from: row.from,
        to: row.to,
      }),
    );

    const indexes: SqliteIndex[] = indexRows.map((indexRow: IndexListRow): SqliteIndex => {
      const iq = '"' + indexRow.name.replaceAll('"', '""') + '"';
      const info = db.query(`PRAGMA index_info(${iq})`).all() as Array<{
        seqno: number;
        cid: number;
        name: string | null;
      }>;
      const ordered = [...info].sort(
        (left: { seqno: number }, right: { seqno: number }): number => left.seqno - right.seqno,
      );
      const indexColumns: string[] = [];
      for (const part of ordered) {
        if (part.name !== null) indexColumns.push(part.name);
      }
      return {
        name: indexRow.name,
        unique: indexRow.unique === 1,
        origin: indexRow.origin,
        partial: indexRow.partial === 1,
        columns: indexColumns,
      };
    });

    return { name: t, columns, foreignKeys, indexes };
  });
}

/**
 * Returns true when `error` is a Node `ENOENT` failure.
 * @param error - Unknown rejection or thrown value.
 * @returns Whether the error code is `ENOENT`.
 */
function isEnoent(error: unknown): boolean {
  return (
    typeof error === 'object' &&
    error !== null &&
    'code' in error &&
    (error as { code: unknown }).code === 'ENOENT'
  );
}

/**
 * Loads the committed database docs into a path → markdown map.
 * Missing `README.md` or a missing `tables` directory yields an empty contribution, not an error.
 * @param repoRoot - Absolute repository root.
 * @returns Repo-relative POSIX paths (`docs/database/...`) to file text.
 */
export async function readCommitted(repoRoot: string): Promise<Map<string, string>> {
  const committed = new Map<string, string>();
  const readmeRel = 'docs/database/README.md';
  try {
    const text = await readFile(path.join(repoRoot, 'docs', 'database', 'README.md'), 'utf8');
    committed.set(readmeRel, text);
  } catch (error) {
    if (!isEnoent(error)) throw error;
  }

  const tablesDir = path.join(repoRoot, 'docs', 'database', 'tables');
  let names: string[];
  try {
    names = await readdir(tablesDir);
  } catch (error) {
    if (!isEnoent(error)) throw error;
    return committed;
  }

  for (const name of names) {
    if (!name.endsWith('.md')) continue;
    const rel = `docs/database/tables/${name}`;
    const text = await readFile(path.join(tablesDir, name), 'utf8');
    committed.set(rel, text);
  }
  return committed;
}

/**
 * Boots the real map-place schema in a temporary database and renders the reference pages.
 * @param repoRoot - Absolute repository root (TypeScript program and source scan).
 * @returns Repo-relative POSIX paths to rendered markdown.
 */
export async function generate(repoRoot: string): Promise<Map<string, string>> {
  const directory = await mkdtemp(path.join(tmpdir(), 'db-schema-reference-'));
  try {
    const file = path.join(directory, 'schema.sqlite');
    const store = new SqliteMapPlaceStore(file);
    store.close();
    const db = new Database(file, { readonly: true });
    let tables: RawTable[];
    try {
      tables = readRawSchema(db);
    } finally {
      db.close();
    }
    const program = createProgram(repoRoot);
    const enums = resolveEnumColumns(program, repoRoot, tables);
    const model = buildSchemaModel(tables, enums);
    const sources = await sourceFiles(repoRoot);
    return renderPages(model, sources, repoRoot);
  } finally {
    await rm(directory, { recursive: true, force: true });
  }
}

/**
 * Writes every rendered page under the repository and deletes stale table pages only.
 * @param rendered - Path → markdown produced by {@link generate}.
 * @returns Counts of files written and stale table pages removed.
 */
async function writeRendered(
  rendered: Map<string, string>,
): Promise<{ written: number; removed: number }> {
  const tablesDir = path.join(REPO_ROOT, 'docs', 'database', 'tables');
  await mkdir(tablesDir, { recursive: true });
  for (const [rel, body] of rendered) {
    const abs = path.join(REPO_ROOT, ...rel.split('/'));
    await mkdir(path.dirname(abs), { recursive: true });
    await writeFile(abs, body);
  }

  let removed = 0;
  const existing = await readdir(tablesDir);
  for (const name of existing) {
    if (!name.endsWith('.md')) continue;
    const rel = `docs/database/tables/${name}`;
    if (!rendered.has(rel)) {
      await rm(path.join(tablesDir, name));
      removed += 1;
    }
  }
  return { written: rendered.size, removed };
}

/**
 * CLI entry for `bun integration/db-schema-reference.ts --write|--check`.
 * @param argv - Arguments after the script name.
 * @returns Exit code: `0` success, `1` docs drift, `2` usage.
 */
export async function runCli(argv: readonly string[]): Promise<number> {
  const mode = argv[0];
  if (argv.length !== 1 || (mode !== '--write' && mode !== '--check')) {
    console.error('Usage: bun integration/db-schema-reference.ts --write|--check');
    return 2;
  }

  const rendered = await generate(REPO_ROOT);
  if (mode === '--write') {
    const { written, removed } = await writeRendered(rendered);
    console.warn(`Wrote ${written} files, removed ${removed} stale`);
    return 0;
  }

  const committed = await readCommitted(REPO_ROOT);
  const diff = compareToCommitted(rendered, committed);
  if (diff.missing.length === 0 && diff.differing.length === 0 && diff.stale.length === 0) {
    console.warn('docs/database is up to date');
    return 0;
  }
  for (const rel of diff.missing) console.error(`missing: ${rel}`);
  for (const rel of diff.differing) console.error(`differs: ${rel}`);
  for (const rel of diff.stale) console.error(`stale: ${rel}`);
  console.error('Run: bun run db:docs');
  return 1;
}

if (import.meta.main) {
  try {
    const code = await runCli(process.argv.slice(2));
    process.exit(code);
  } catch (error) {
    console.error(error);
    process.exit(1);
  }
}
